//! Replay of `tests/fixtures/agent-event-projector/oracle.json`, generated by
//! the real TS `mapAgentEvent` (see the fixture README).
//!
//! Every expectation is produced by the unmodified baseline TS: valid events
//! replay as frames + `persist` calls, structurally invalid ones replay as
//! `String(error)`. Deep-nesting cases are built identically on both sides and
//! pinned by the probe in `_tmp/20261022-a72-pr2-projector/probe-fix1.mts`.

use super::*;
use std::sync::Mutex;

const ORACLE: &str = include_str!("../../../tests/fixtures/agent-event-projector/oracle.json");
const PERCENT: &str = "/tmp/pdrs-agent-event-projector";
const RANGE_ERROR: &str = "RangeError: Maximum call stack size exceeded";

#[derive(Default)]
struct RecordingStore {
    calls: Mutex<Vec<JsValue>>,
}

impl GatewayToolResultArtifactStorePort for RecordingStore {
    fn persist(&self, input: &GatewayToolResultArtifactInput) -> ProjectionResult<Option<String>> {
        let bytes = utf8_len(input.text.units());
        // Mirrors the fixture stand-in in `generate.mts`: only the over-
        // threshold branch touches `safePathPart`, which throws on a
        // non-string path field before the call is recorded.
        let returned = if bytes > DEFAULT_ARTIFACT_THRESHOLD_BYTES {
            Some(format!(
                "{}/{}/{}/{}.txt",
                PERCENT,
                safe_path_part_js(&input.session_id)?,
                safe_path_part_js(&input.turn_id)?,
                safe_path_part_js(&input.tool_call_id)?,
            ))
        } else {
            None
        };
        let record = object([
            ("sessionId", input.session_id.clone()),
            ("turnId", input.turn_id.clone()),
            ("toolCallId", input.tool_call_id.clone()),
            ("text", JsValue::String(input.text.clone())),
            ("bytes", number(bytes as f64)),
            (
                "returned",
                returned
                    .as_deref()
                    .map_or(JsValue::Undefined, JsValue::from),
            ),
        ]);
        self.calls.lock().unwrap().push(record);
        Ok(returned)
    }
}

fn array(value: &JsValue) -> &[JsValue] {
    items(value)
}

fn stringified(value: &JsValue) -> String {
    pilotdeck_protocol::stringify_json(value)
        .expect("frame is JSON-serializable")
        .expect("frame is not undefined")
}

fn utf8(value: &JsValue) -> String {
    value
        .as_string()
        .expect("string value")
        .to_utf8()
        .expect("utf-8 string")
}

fn deep_array(depth: usize) -> JsValue {
    let mut value = text("leaf");
    for _ in 0..depth {
        value = JsValue::Array(vec![value]);
    }
    value
}

fn deep_object(depth: usize) -> JsValue {
    let mut value = text("leaf");
    for _ in 0..depth {
        value = object([("n", value)]);
    }
    value
}

fn assert_range_error(result: ProjectionResult<Vec<JsValue>>, case: &str) {
    assert!(result.is_err(), "case {case:?} should throw");
    let error = match result {
        Err(error) => error,
        Ok(_) => unreachable!("asserted above"),
    };
    assert_eq!(error.to_string(), RANGE_ERROR, "case {case:?} error");
}

#[test]
fn agent_event_projections_match_ts_oracle() {
    let oracle = crate::test_baseline::oracle(ORACLE);
    let cases = array(field(&oracle, "cases"));
    assert_eq!(cases.len(), 192, "oracle case count");

    for case in cases {
        let name = field(case, "name")
            .as_string()
            .and_then(|value| value.to_utf8().ok())
            .expect("case name");
        let event = field(case, "event");
        let run_id = field(case, "runId")
            .as_string()
            .and_then(|value| value.to_utf8().ok())
            .expect("case runId");
        let forward = field(case, "forwardSubagentText")
            .as_bool()
            .expect("case forwardSubagentText");
        let store = Arc::new(RecordingStore::default());
        let options = GatewayAgentEventProjectorOptions {
            tool_result_artifacts: Some(store.clone()),
            forward_subagent_text: forward,
        };
        let result = map_agent_event(event, &run_id, options);

        let expected_error = field(case, "error");
        let actual = match expected_error.as_string() {
            Some(expected) => {
                let expected = expected.to_utf8().expect("utf-8 error text");
                assert!(result.is_err(), "case {name:?} should throw");
                let error = match result {
                    Err(error) => error,
                    Ok(_) => unreachable!("asserted above"),
                };
                assert_eq!(error.to_string(), expected, "case {name:?} error");
                Vec::new()
            }
            None => result.expect("case should project"),
        };

        let expected = array(field(case, "frames"));
        assert_eq!(actual.len(), expected.len(), "case {name:?} frame count");
        for (index, (actual, expected)) in actual.iter().zip(expected).enumerate() {
            assert_eq!(
                stringified(actual),
                stringified(expected),
                "case {name:?} frame {index}"
            );
        }

        let expected_persist = array(field(case, "persist"));
        let recorded = store.calls.lock().unwrap();
        assert_eq!(
            recorded.len(),
            expected_persist.len(),
            "case {name:?} persist count"
        );
        for (index, (actual, expected)) in recorded.iter().zip(expected_persist).enumerate() {
            assert_eq!(
                stringified(actual),
                stringified(expected),
                "case {name:?} persist {index}"
            );
        }
    }
}

#[test]
fn unknown_and_missing_event_types_project_nothing() {
    for event in [
        object([("type", text("future_event"))]),
        object([("sessionId", text("s"))]),
        JsValue::String(JsString::from("turn_started")),
    ] {
        assert!(
            map_agent_event(
                &event,
                "run-1",
                GatewayAgentEventProjectorOptions::default()
            )
            .expect("unknown events project nothing")
            .is_empty()
        );
    }
}

#[test]
fn null_and_undefined_events_throw_the_ts_type_error() {
    let null_result = map_agent_event(
        &JsValue::Null,
        "run-1",
        GatewayAgentEventProjectorOptions::default(),
    );
    assert!(null_result.is_err(), "null event should throw");
    let null_error = match null_result {
        Err(error) => error,
        Ok(_) => unreachable!("asserted above"),
    };
    assert_eq!(
        null_error.to_string(),
        "TypeError: Cannot read properties of null (reading 'type')"
    );

    let undefined_result = map_agent_event(
        &JsValue::Undefined,
        "run-1",
        GatewayAgentEventProjectorOptions::default(),
    );
    assert!(undefined_result.is_err(), "undefined event should throw");
    let undefined_error = match undefined_result {
        Err(error) => error,
        Ok(_) => unreachable!("asserted above"),
    };
    assert_eq!(
        undefined_error.to_string(),
        "TypeError: Cannot read properties of undefined (reading 'type')"
    );
}

/// P0: a deep tool `data` value is a catchable `RangeError` in TS; the Rust
/// port must return it instead of exhausting the native stack. Depth 30,000 is
/// where the probe (`_tmp/.../probe-fix1.mts`) measured a TS `RangeError` for
/// both shapes (at 2,200 the array already throws but the object does not).
/// Rust errors earlier (depth > `MAX_ARRAY_DEPTH`, the repository's
/// conservative bound); see the divergence note in RESULT.
#[test]
fn deep_tool_data_returns_ts_range_error_instead_of_overflowing_the_stack() {
    for (case, data) in [
        ("deep-tool-data-array", deep_array(30_000)),
        ("deep-tool-data-object", deep_object(30_000)),
    ] {
        let event = object([
            ("type", text("tool_result")),
            ("sessionId", text("s")),
            ("turnId", text("t")),
            (
                "result",
                object([
                    ("type", text("success")),
                    ("toolCallId", text("c")),
                    ("toolName", text("tool")),
                    ("content", JsValue::Array(Vec::new())),
                    ("startedAt", text("a")),
                    ("completedAt", text("b")),
                    ("data", data),
                ]),
            ),
        ]);
        assert_range_error(
            map_agent_event(
                &event,
                "run-1",
                GatewayAgentEventProjectorOptions::default(),
            ),
            case,
        );
    }
}

/// P1: `JSON.stringify` throws on deep containers; TS then falls back to
/// `String(value)`, which renders an object as `[object Object]` at any depth.
/// The probe measured `JSON.stringify` still succeeding at 3,000 and throwing
/// at 30,000, so 30,000 is the depth with a genuine TS fallback.
#[test]
fn deep_provider_raw_and_args_preview_fall_back_to_ts_string_conversion() {
    let failed = object([
        ("type", text("turn_failed")),
        (
            "error",
            object([
                ("code", text("agent_model_error")),
                ("message", text("failed")),
                (
                    "details",
                    object([("provider", text("p")), ("raw", deep_object(30_000))]),
                ),
            ]),
        ),
    ]);
    let frames = map_agent_event(
        &failed,
        "run-1",
        GatewayAgentEventProjectorOptions::default(),
    )
    .expect("turn_failed projects");
    let provider_error = field(&frames[0], "providerError");
    assert_eq!(utf8(field(provider_error, "raw")), "[object Object]");

    let calls = object([
        ("type", text("tool_calls_detected")),
        (
            "calls",
            JsValue::Array(vec![object([
                ("id", text("c1")),
                ("name", text("tool")),
                ("input", deep_object(30_000)),
            ])]),
        ),
    ]);
    let frames = map_agent_event(
        &calls,
        "run-1",
        GatewayAgentEventProjectorOptions::default(),
    )
    .expect("tool_calls_detected projects");
    assert_eq!(utf8(field(&frames[0], "argsPreview")), "[object Object]");
}

/// P1: `persist` is fire-and-forget (`void this.write(...)`); projection must
/// not wait for the advisory directory/file work.
#[test]
fn advisory_persist_returns_before_the_write_completes() {
    use std::sync::mpsc;
    use std::time::{Duration, Instant};

    let (started_tx, started_rx) = mpsc::channel::<()>();
    let (release_tx, release_rx) = mpsc::channel::<()>();
    let release_rx = Mutex::new(release_rx);
    let store = GatewayToolResultArtifactStore::with_io(
        std::env::temp_dir().join("pdrs-projector-async"),
        4,
        Arc::new(move |_path| {
            let _ = started_tx.send(());
            let _ = release_rx
                .lock()
                .unwrap()
                .recv_timeout(Duration::from_secs(5));
            Ok(())
        }),
        Arc::new(|_path, _bytes| Ok(())),
    );
    let input = GatewayToolResultArtifactInput {
        session_id: text("s"),
        turn_id: text("t"),
        tool_call_id: text("c"),
        text: JsString::from("abcde"),
    };
    let began = Instant::now();
    let path = store
        .persist(&input)
        .expect("persisted")
        .expect("returned above threshold");
    let elapsed = began.elapsed();
    started_rx
        .recv_timeout(Duration::from_secs(5))
        .expect("advisory write started");
    assert!(
        elapsed < Duration::from_secs(1),
        "persist blocked for {elapsed:?}"
    );
    release_tx.send(()).expect("release writer");
    store.wait_for_pending();
    assert!(path.ends_with(".txt"));
}

/// P2: TS uses `path.resolve`, so `..`/`.` path parts are normalized.
#[test]
fn default_store_resolves_dot_segments_like_ts() {
    let store = GatewayToolResultArtifactStore::with_io(
        "/tmp/pdrs-probe-root",
        4,
        Arc::new(|_path| Ok(())),
        Arc::new(|_path, _bytes| Ok(())),
    );
    let input = GatewayToolResultArtifactInput {
        session_id: text(".."),
        turn_id: text("."),
        tool_call_id: text(".."),
        text: JsString::from("abcde"),
    };
    assert_eq!(
        store
            .persist(&input)
            .expect("persisted")
            .expect("above threshold"),
        "/tmp/...txt"
    );
    store.wait_for_pending();
}

#[test]
fn default_store_only_persists_above_the_byte_threshold() {
    let root = std::env::temp_dir().join(format!("pdrs-projector-store-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&root);
    let store = GatewayToolResultArtifactStore::new(&root, 4);
    let short = GatewayToolResultArtifactInput {
        session_id: text("s"),
        turn_id: text("t"),
        tool_call_id: text("c"),
        text: JsString::from("abcd"),
    };
    assert_eq!(store.persist(&short).expect("persisted"), None);
    let long = GatewayToolResultArtifactInput {
        text: JsString::from("abcde"),
        ..short
    };
    let path = store
        .persist(&long)
        .expect("persisted")
        .expect("above threshold");
    store.wait_for_pending();
    assert_eq!(std::fs::read_to_string(&path).unwrap(), "abcde");
    assert!(std::path::Path::new(&path).starts_with(root.join("s").join("t")));
    let _ = std::fs::remove_dir_all(&root);
}

/// Fix round 3: `persist` passes the path fields through unchanged below the
/// threshold, but `safePathPart(...).trim()` throws above it for a non-string
/// `sessionId`/`turnId`/`toolCallId` (TS evaluates them in that order).
#[test]
fn default_store_throws_on_non_string_path_part_like_ts() {
    let store = GatewayToolResultArtifactStore::with_io(
        "/tmp/pdrs-probe-root",
        4,
        Arc::new(|_path| Ok(())),
        Arc::new(|_path, _bytes| Ok(())),
    );
    let short = GatewayToolResultArtifactInput {
        session_id: number(123.0),
        turn_id: JsValue::Bool(true),
        tool_call_id: JsValue::Array(vec![number(1.0), number(2.0)]),
        text: JsString::from("abcd"),
    };
    assert_eq!(
        store.persist(&short).expect("below threshold"),
        None,
        "below the threshold the raw values are recorded and never trimmed"
    );
    for (field, value) in [
        ("sessionId", number(123.0)),
        ("turnId", JsValue::Bool(true)),
        ("toolCallId", JsValue::Array(vec![number(1.0), number(2.0)])),
    ] {
        let input = GatewayToolResultArtifactInput {
            session_id: text("s"),
            turn_id: text("t"),
            tool_call_id: text("c"),
            text: JsString::from("abcde"),
        };
        let input = match field {
            "sessionId" => GatewayToolResultArtifactInput {
                session_id: value,
                ..input
            },
            "turnId" => GatewayToolResultArtifactInput {
                turn_id: value,
                ..input
            },
            "toolCallId" => GatewayToolResultArtifactInput {
                tool_call_id: value,
                ..input
            },
            _ => unreachable!("known field"),
        };
        let error = store
            .persist(&input)
            .expect_err("non-string path part throws above the threshold");
        assert_eq!(
            error.to_string(),
            "TypeError: value.trim is not a function",
            "case {field}"
        );
    }
    store.wait_for_pending();
}

/// A `tool_result` whose joined text is over the 4096-byte advisory threshold,
/// so `persist` starts a background write.
fn persistable_tool_result_event() -> JsValue {
    object([
        ("type", text("tool_result")),
        ("sessionId", text("s")),
        ("turnId", text("t")),
        (
            "result",
            object([
                ("type", text("success")),
                ("toolCallId", text("c")),
                ("toolName", text("bash")),
                (
                    "content",
                    JsValue::Array(vec![object([
                        ("type", text("text")),
                        ("text", JsValue::String(JsString::from("x".repeat(5_000)))),
                    ])]),
                ),
            ]),
        ),
    ])
}

/// P1: `mapAgentEvent`'s facade builds a throwaway projector, so a `Drop` that
/// joined in-flight advisory writes made the facade wait for disk (and hang on
/// a stalled writer). TS's facade uses a process-level projector with
/// `void this.write(...)`. The facade must return while the write is blocked.
#[test]
fn map_agent_event_returns_before_a_blocked_artifact_write() {
    use std::sync::mpsc;
    use std::time::Duration;

    let (started_tx, started_rx) = mpsc::channel::<()>();
    let (release_tx, release_rx) = mpsc::channel::<()>();
    let release_rx = Mutex::new(release_rx);
    let store = GatewayToolResultArtifactStore::with_io(
        std::env::temp_dir().join("pdrs-projector-facade-async"),
        4,
        Arc::new(|_path| Ok(())),
        Arc::new(move |_path, _bytes| {
            let _ = started_tx.send(());
            // Blocks until the test releases it after the facade-return check;
            // a synchronous-write mutant must not be able to hang the suite.
            let _ = release_rx.lock().unwrap().recv();
            Ok(())
        }),
    );
    let options = GatewayAgentEventProjectorOptions {
        tool_result_artifacts: Some(Arc::new(store)),
        forward_subagent_text: false,
    };
    let event = persistable_tool_result_event();
    let (done_tx, done_rx) = mpsc::channel::<bool>();
    std::thread::spawn(move || {
        let result = map_agent_event(&event, "run-1", options);
        let _ = done_tx.send(result.is_ok());
    });
    started_rx
        .recv_timeout(Duration::from_secs(10))
        .expect("advisory write started");
    let returned = done_rx.recv_timeout(Duration::from_secs(5));
    let _ = release_tx.send(());
    assert_eq!(
        returned.ok(),
        Some(true),
        "the facade must return before the advisory write completes"
    );
}

/// P1 (same fix): dropping the store must not join a blocked advisory write.
#[test]
fn dropping_the_store_does_not_join_a_blocked_artifact_write() {
    use std::sync::mpsc;
    use std::time::Duration;

    let (started_tx, started_rx) = mpsc::channel::<()>();
    let (release_tx, release_rx) = mpsc::channel::<()>();
    let release_rx = Mutex::new(release_rx);
    let store = GatewayToolResultArtifactStore::with_io(
        std::env::temp_dir().join("pdrs-projector-drop-async"),
        4,
        Arc::new(|_path| Ok(())),
        Arc::new(move |_path, _bytes| {
            let _ = started_tx.send(());
            let _ = release_rx
                .lock()
                .unwrap()
                .recv_timeout(Duration::from_secs(30));
            Ok(())
        }),
    );
    let input = GatewayToolResultArtifactInput {
        session_id: text("s"),
        turn_id: text("t"),
        tool_call_id: text("c"),
        text: JsString::from("abcde"),
    };
    assert!(
        store.persist(&input).expect("persisted").is_some(),
        "queued above threshold"
    );
    started_rx
        .recv_timeout(Duration::from_secs(10))
        .expect("advisory write started");

    let (dropped_tx, dropped_rx) = mpsc::channel::<()>();
    let handle = std::thread::spawn(move || {
        drop(store);
        let _ = dropped_tx.send(());
    });
    let dropped = dropped_rx.recv_timeout(Duration::from_secs(5)).is_ok();
    let _ = release_tx.send(());
    handle.join().ok();
    assert!(dropped, "dropping the store must not wait for the writer");
}

/// P1: an advisory write beyond any in-flight count must still be queued. The
/// old bounded-thread design dropped the 9th write while `persist` kept
/// returning a path, so `resultPath` pointed at a file that would never exist.
#[test]
fn every_advisory_write_is_eventually_persisted() {
    use std::sync::Condvar;

    let written = Arc::new(Mutex::new(Vec::<String>::new()));
    let gate = Arc::new((Mutex::new(false), Condvar::new()));
    let write_hook = {
        let written = written.clone();
        let gate = gate.clone();
        Arc::new(move |path: &std::path::Path, _bytes: &[u8]| {
            let (lock, condvar) = &*gate;
            let mut open = lock.lock().unwrap();
            while !*open {
                open = condvar.wait(open).unwrap();
            }
            drop(open);
            written.lock().unwrap().push(path.display().to_string());
            Ok(())
        })
    };
    let store = GatewayToolResultArtifactStore::with_io(
        std::env::temp_dir().join("pdrs-projector-many-writes"),
        4,
        Arc::new(|_path| Ok(())),
        write_hook,
    );
    // A mutant that performs the write synchronously would otherwise block the
    // persist loop (and this test) forever; force the gate open after a bound.
    {
        let gate = gate.clone();
        let _ = std::thread::spawn(move || {
            std::thread::sleep(std::time::Duration::from_secs(1));
            let (lock, condvar) = &*gate;
            *lock.lock().unwrap() = true;
            condvar.notify_all();
        });
    }
    let mut paths = Vec::new();
    for index in 0..12 {
        let input = GatewayToolResultArtifactInput {
            session_id: text("s"),
            turn_id: text("t"),
            tool_call_id: text(format!("c{index}")),
            text: JsString::from("abcde"),
        };
        paths.push(
            store
                .persist(&input)
                .expect("persisted")
                .expect("advisory write queued"),
        );
    }
    {
        let (lock, condvar) = &*gate;
        *lock.lock().unwrap() = true;
        condvar.notify_all();
    }
    store.wait_for_pending();
    let written = written.lock().unwrap();
    assert_eq!(written.len(), 12, "written: {written:?}");
    for path in &paths {
        assert!(written.contains(path), "missing advisory write: {path}");
    }
}

